      c.appendChild(icon(ic, `module/${t}/fg`, 20)); c.appendChild(await txt(n, 'Number/Medium', `module/${t}/fg`)); const lt = await txt(l, 'Label/Medium', 'color/on-surface'); c.appendChild(lt); wrapText(lt);
