      const sr = AL('HORIZONTAL'); sr.itemSpacing = 0; c.appendChild(sr); for (let k = 0; k < i; k++) sr.appendChild(icon('star', 'color/outline', 12));
      c.appendChild(await txt(n + ' children', 'Label/Small', 'color/on-surface'));
