    await seg(b, 'Beneficiary status', ['Alive', 'Died'], 0);
    select(b, 'Case status *', 'Suspected');
    await seg(b, 'Kala-azar RDT', ['Positive', 'Negative', 'Not done'], 2);
    select(b, 'Referred to', 'CHC Rajnagar'); date(b, 'Follow-up date', '09 Nov 2026');
