// ===== 48-stage-ids.js =====
// Utility: writes a "Section IDs" text node listing key frame ids (for share links), then removes nothing else.
const ID_FRAMES = ['M2.19-13', 'M2.19-17', 'M2.19-19', 'M2.19-22', 'M2.19-27', 'M2.19-28', 'M2.19-36', 'M2.19-39', 'M2.19-41', 'M2.19-54',
  'M2.18-P1', 'M2.2-17', 'M2.3-10', 'M2.4-19', 'M2.5-07', 'M2.6-09', 'M2.7-25', 'M2.8-20', 'M2.8-23', 'M2.9-13', 'M2.9-25', 'M2.10-08', 'M2.11-03', 'M2.11-11', 'M2.12-07', 'M2.13-06'];
async function buildStageIds(ctx) {
  const sp = ctx.pages.screens; await figma.setCurrentPageAsync(sp);
  for (const n of [...sp.children]) if (n.name === 'Section IDs') n.remove();
  const byKey = {};
  for (const s of sp.children) if (s.type === 'SECTION') for (const f of s.children) if (f.type === 'FRAME') { const k = f.name.split(' · ')[0].trim(); if (!byKey[k]) byKey[k] = f; }
  const lines = ID_FRAMES.map((k) => (byKey[k] ? byKey[k].id + '  |  ' + byKey[k].name : 'MISSING ' + k));
  const t = figma.createText(); t.name = 'Section IDs'; await t.setTextStyleIdAsync(ctx.TS['Title/Large'].id);
  t.characters = lines.join('\n'); sp.appendChild(t); t.x = -3000; t.y = 0;
  figma.viewport.scrollAndZoomIntoView([t]);
  return ['ids: ' + lines.length];
}

// ===== 49-stage-tokens.js =====
// Utility: dumps all variables (resolved) + text styles into a "Token dump" text node (2 columns).
async function buildStageTokens(ctx) {
  const sp = ctx.pages.screens; await figma.setCurrentPageAsync(sp);
  for (const n of [...sp.children]) if (n.name.startsWith('Token dump')) n.remove();
  const hex = (c) => '#' + [c.r, c.g, c.b].map((x) => Math.round(x * 255).toString(16).padStart(2, '0')).join('').toUpperCase();
  const vars = await figma.variables.getLocalVariablesAsync();
  const byId = {}; for (const v of vars) byId[v.id] = v;
  const resolve = (v) => { let val = Object.values(v.valuesByMode)[0]; let g = 0; while (val && val.type === 'VARIABLE_ALIAS' && g++ < 10) { const t = byId[val.id]; val = t ? Object.values(t.valuesByMode)[0] : null; } return val; };
  const lines = [];
  for (const v of vars) { if (v.hiddenFromPublishing && v.resolvedType === 'COLOR' && !v.name.includes('/')) continue; const val = resolve(v); if (val == null) continue; const s = v.resolvedType === 'COLOR' ? hex(val) + (val.a !== undefined && val.a < 1 ? ' a' + val.a.toFixed(2) : '') : String(val); lines.push(v.name + ' = ' + s); }
  const ts = await figma.getLocalTextStylesAsync();
  for (const t of ts) lines.push('TS ' + t.name + ' = ' + t.fontName.family + ' ' + t.fontName.style + ' ' + t.fontSize + '/' + (t.lineHeight.unit === 'PIXELS' ? t.lineHeight.value : t.lineHeight.unit) + ' ls' + (t.letterSpacing.value || 0));
  lines.sort();
  const half = Math.ceil(lines.length / 2); const made = [];
  for (const [i, part] of [[0, lines.slice(0, half)], [1, lines.slice(half)]]) {
    const t = figma.createText(); t.name = 'Token dump ' + i; await t.setTextStyleIdAsync(ctx.TS['Body/Large'].id);
    t.characters = part.join('\n'); sp.appendChild(t); t.x = -9000 + i * 900; t.y = 0; made.push(t);
  }
  figma.viewport.scrollAndZoomIntoView(made);
  return ['tokens: ' + lines.length];
}

// ===== 50-stage-spec.js =====
// Utility: dumps a developer spec (geometry, padding, gap, radius, fills, strokes, fonts) of SPEC_FRAME into a text node.
const SPEC_FRAME = 'M2.2-02 ·';
async function buildStageSpec(ctx) {
  const sp = ctx.pages.screens; await figma.setCurrentPageAsync(sp);
  for (const n of [...sp.children]) if (n.name.startsWith('Spec dump')) n.remove();
  let target = null;
  for (const s of sp.children) { if (s.type === 'SECTION') { for (const f of s.children) if (f.name.startsWith(SPEC_FRAME)) target = f; } else if (s.name.startsWith(SPEC_FRAME)) target = s; }
  if (!target) throw new Error('frame not found ' + SPEC_FRAME);
  const hex = (p) => { if (!p || p.type !== 'SOLID') return p ? p.type : ''; const c = p.color; return '#' + [c.r, c.g, c.b].map((x) => Math.round(x * 255).toString(16).padStart(2, '0')).join('').toUpperCase() + (p.opacity !== undefined && p.opacity < 1 ? '@' + p.opacity.toFixed(2) : ''); };
  const lines = []; const fx = target.absoluteTransform[0][2], fy = target.absoluteTransform[1][2];
  const walk = (n, d) => {
    if (!n.visible) return;
    if (d > 10) return;
    const x = Math.round(n.absoluteTransform[0][2] - fx), y = Math.round(n.absoluteTransform[1][2] - fy);
    let l = '  '.repeat(d) + n.type[0] + ' ' + n.name.slice(0, 28) + ` [${x},${y} ${Math.round(n.width)}x${Math.round(n.height)}]`;
    if ('fills' in n && Array.isArray(n.fills) && n.fills.length && n.fills[0].visible !== false) l += ' bg' + hex(n.fills[0]);
    if ('strokes' in n && n.strokes.length && n.strokeWeight) l += ' st' + hex(n.strokes[0]) + '/' + (typeof n.strokeWeight === 'number' ? n.strokeWeight : 'mix');
    if ('cornerRadius' in n && n.cornerRadius && n.cornerRadius !== figma.mixed) l += ' r' + n.cornerRadius;
    if ('layoutMode' in n && n.layoutMode !== 'NONE') l += ` ${n.layoutMode[0]} p${n.paddingTop},${n.paddingRight},${n.paddingBottom},${n.paddingLeft} g${n.itemSpacing}`;
    if ('layoutSizingHorizontal' in n) l += ` sz${n.layoutSizingHorizontal[0]}${n.layoutSizingVertical[0]}`;
    if ('layoutMode' in n && n.layoutMode !== 'NONE') l += ` al${n.primaryAxisAlignItems[0]}${n.counterAxisAlignItems[0]}`;
    if (n.type === 'TEXT') { const fn = n.fontName === figma.mixed ? 'mix' : n.fontName.style; l += ` "${n.characters.slice(0, 40).replace(/\n/g, ' ')}" ${n.fontSize}/${n.lineHeight && n.lineHeight.unit === 'PIXELS' ? n.lineHeight.value : 'auto'} ${fn}`; }
    lines.push(l);
    if ('children' in n && n.type !== 'TEXT') for (const c of n.children) walk(c, d + 1);
  };
  walk(target, 0);
  const cols = 2, per = Math.ceil(lines.length / cols); const made = [];
  for (let i = 0; i < cols; i++) {
    const t = figma.createText(); t.name = 'Spec dump ' + i; await t.setTextStyleIdAsync(ctx.TS['Body/Small'].id);
    t.characters = lines.slice(i * per, (i + 1) * per).join('\n') || ' '; sp.appendChild(t); t.x = -16000 + i * 1100; t.y = 0; made.push(t);
  }
  figma.viewport.scrollAndZoomIntoView(made);
  const sent = await sendSpecToLocal('FRAME ' + target.name + ' ' + Math.round(target.width) + 'x' + Math.round(target.height) + '\n' + lines.join('\n'));
  return ['spec lines: ' + lines.length + (sent ? ' (sent to localhost)' : ' (local receiver not running)')];
}

// Dev only: posts the spec text to http://localhost:8765 (receiver: design/figma-plugin/spec_receiver.py) so it can be read exactly.
function sendSpecToLocal(text) {
  return new Promise((resolve) => {
    figma.showUI(`<script>onmessage=(e)=>{const t=e.data.pluginMessage;fetch('http://localhost:8765/spec',{method:'POST',body:t}).then(()=>parent.postMessage({pluginMessage:'ok'},'*')).catch(()=>parent.postMessage({pluginMessage:'fail'},'*'));}</script>`, { visible: false });
    const timer = setTimeout(() => resolve(false), 5000);
    figma.ui.onmessage = (m) => { clearTimeout(timer); resolve(m === 'ok'); };
    figma.ui.postMessage(text);
  });
}

// ===== 90-main.js =====
// ---------------------------------------------------------------------------
// Command dispatcher
// ---------------------------------------------------------------------------
// Stages built by "Phase 2: build current stage(s)". Change this list to move on
// (no manifest change / re-import needed).
const CURRENT_STAGES = ['spec'];

// "Phase 2: show current stage(s)" zooms to frames whose names start with these prefixes (empty = whole sections).
const REVIEW_FOCUS = ['M2.19-01 ·'];

const STAGES = {
  '2.0': { name: '2.0 · Patterns, form kit & states', build: (ctx) => buildStage20(ctx) },
  '2.1': { name: '2.1 · Gamification', build: (ctx) => buildStage21(ctx) },
  '2.2': { name: '2.2 · Maternal health', build: (ctx) => buildStage22(ctx) },
  '2.3': { name: '2.3 · Eligible couple', build: (ctx) => buildStage23(ctx) },
  '2.4': { name: '2.4 · Child care & infant', build: (ctx) => buildStage24(ctx) },
  '2.5': { name: '2.5 · Immunization', build: (ctx) => buildStage25(ctx) },
  '2.6': { name: '2.6 · High risk & CHO', build: (ctx) => buildStage26(ctx) },
  '2.7': { name: '2.7 · NCD & TB', build: (ctx) => buildStage27(ctx) },
  '2.8': { name: '2.8 · Disease control & check-up', build: (ctx) => buildStage28(ctx) },
  '2.9': { name: '2.9 · Death reports & village forms', build: (ctx) => buildStage29(ctx) },
  '2.10': { name: '2.10 · ABHA', build: (ctx) => buildStage210(ctx) },
  '2.11': { name: '2.11 · Profile, incentives & utilities', build: (ctx) => buildStage211(ctx) },
  '2.12': { name: '2.12 · Supervisor', build: (ctx) => buildStage212(ctx) },
  '2.13': { name: '2.13 · Remaining screens, languages & prototype', build: (ctx) => buildStage213(ctx) },
  '2.14': { name: '2.14 · Navigation', build: (ctx) => buildStage214(ctx) },
  '2.15': { name: '2.15 · Complete form specs A–M (every field)', build: (ctx) => buildStage215(ctx) },
  '2.16': { name: '2.16 · Complete form specs N–Z (every field)', build: (ctx) => buildStage216(ctx) },
  '2.17': { name: '2.17 · Complete card specs (every list card)', build: (ctx) => buildStage217(ctx) },
  '2.18': { name: '2.18 · Gap-fix patterns (shared)', build: (ctx) => buildStage218(ctx) },
  '2.19': { name: '2.19 · Core screens v2 (login, home, household, beneficiary)', build: (ctx) => buildStage219(ctx) },
  'ids': { name: 'Section IDs', build: (ctx) => buildStageIds(ctx) },
  'tokens': { name: 'Token dump', build: (ctx) => buildStageTokens(ctx) },
  'spec': { name: 'Spec dump', build: (ctx) => buildStageSpec(ctx) },
};

async function main() {
  const ctx = await loadContext();
  const cmd = figma.command || 'all';

  if (cmd === 'review-screens' || cmd === 'review-all') {
    const sp = ctx.pages.screens; await figma.setCurrentPageAsync(sp);
    const nodes = sp.children.filter((n) => cmd === 'review-all' || SCREEN_PREFIXES.some((p) => n.name.startsWith(p)));
    figma.currentPage.selection = [];
    figma.viewport.scrollAndZoomIntoView(nodes);
    return 'Showing ' + nodes.length + ' screens';
  }

  if (cmd === 'stage-current' || cmd === 'stage-review') {
    const done = [];
    for (const id of CURRENT_STAGES) {
      const st = STAGES[id];
      if (!st) throw new Error('Stage ' + id + ' is not implemented yet');
      if (cmd === 'stage-current') done.push(...(await st.build(ctx)));
    }
    const sp = ctx.pages.screens; await figma.setCurrentPageAsync(sp);
    const secs = sp.children.filter((n) => CURRENT_STAGES.some((id) => n.name === STAGES[id].name));
    let focus = secs;
    if (cmd === 'stage-review' && REVIEW_FOCUS.length) {
      focus = [];
      for (const sec of secs) for (const c of sec.children) if (REVIEW_FOCUS.some((p) => c.name.startsWith(p))) focus.push(c);
    }
    figma.currentPage.selection = [];
    if (focus.length && !CURRENT_STAGES.includes('2.14')) figma.viewport.scrollAndZoomIntoView(focus);
    return cmd === 'stage-current' ? '✅ Built: ' + done.join(', ') : 'Showing stages ' + CURRENT_STAGES.join(', ');
  }

  const done = [];
  if (cmd === 'screens' || cmd === 'all') done.push(...(await buildScreens(ctx)));
  if (cmd === 'foundations' || cmd === 'all') done.push(...(await buildFoundations(ctx)));
  return '✅ Built: ' + done.join(', ');
}

main()
  .then((msg) => figma.closePlugin(msg))
  .catch(async (e) => { if (CURRENT_STAGES.includes('spec')) await sendSpecToLocal('ERROR ' + (e && e.message ? e.message : String(e))); figma.closePlugin('❌ FLW builder error: ' + (e && e.message ? e.message : String(e)) + (e && e.stack ? ' @ ' + String(e.stack).split('\n')[1] : '')); });
